package cl.bolsillo.app;
import android.app.Notification;import android.service.notification.*;import android.os.Bundle;import org.json.*;
public class BankNotificationListener extends NotificationListenerService {
 @Override public void onListenerConnected(){super.onListenerConnected();NativeStore.settings(this).edit().putBoolean("listenerConnected",true).apply();try{StatusBarNotification[] active=getActiveNotifications();if(active!=null)for(StatusBarNotification notification:active)if(System.currentTimeMillis()-notification.getPostTime()<=900000)process(notification,true);}catch(Exception ignored){}}
 @Override public void onListenerDisconnected(){NativeStore.settings(this).edit().putBoolean("listenerConnected",false).apply();super.onListenerDisconnected();}
 static String content(Bundle e){java.util.List<String> parts=new java.util.ArrayList<>();for(String key:new String[]{Notification.EXTRA_TITLE,Notification.EXTRA_TEXT,Notification.EXTRA_BIG_TEXT,Notification.EXTRA_SUB_TEXT,Notification.EXTRA_SUMMARY_TEXT}){CharSequence part=e.getCharSequence(key);if(part!=null)addPart(parts,part.toString());}CharSequence[] lines=e.getCharSequenceArray(Notification.EXTRA_TEXT_LINES);if(lines!=null)for(CharSequence line:lines)if(line!=null)addPart(parts,line.toString());return String.join("\n",parts);}
 static void addPart(java.util.List<String> parts,String raw){String value=raw.trim();if(value.isEmpty())return;for(String old:parts)if(old.contains(value))return;parts.removeIf(value::contains);parts.add(value);}
 static void reconnect(android.content.Context c){if(!NativeStore.settings(c).getBoolean("capture",false))return;try{requestRebind(new android.content.ComponentName(c,BankNotificationListener.class));}catch(Exception ignored){}}
 @Override public void onNotificationPosted(StatusBarNotification sbn){process(sbn,false);}
 private void process(StatusBarNotification sbn,boolean recovered){if(sbn.getPackageName().equals(getPackageName()))return;if(!NativeStore.settings(this).getBoolean("capture",false))return;JSONObject selected=Detection.source(this,sbn.getPackageName());if(selected==null)return;Notification n=sbn.getNotification();if((n.flags&(Notification.FLAG_GROUP_SUMMARY|Notification.FLAG_ONGOING_EVENT))!=0)return;Bundle extras=n.extras;if(extras==null)return;String title=String.valueOf(extras.getCharSequence(Notification.EXTRA_TITLE,"")),text=content(extras);if(text.length()>5000)text=text.substring(0,5000);final String message=text;final JSONObject source;try{source=new JSONObject(selected.toString());}catch(Exception error){return;}boolean email=source.optString("kind").equals("email")||sbn.getPackageName().equals("com.google.android.gm");if(email){String normalized=BankNotificationParser.normalize(message);boolean mach=normalized.contains("mach"),estado=normalized.contains("bancoestado")||normalized.contains("banco estado");try{source.put("kind",mach==estado?"email":mach?"mach":"bancoestado").put("label","Gmail");}catch(Exception ignored){}}
 final boolean fromEmail=email;NativeSync.EXEC.execute(()->{try{BankNotificationParser.Candidate parsed=NotificationPatterns.parse(this,message,title,source);if(parsed==null){NativeStore.logNotice(this,selected,"Sin movimiento reconocible",sbn.getPostTime());Detection.status(this,selected.optString("label"),"Aviso recibido, sin movimiento reconocible");return;}BankNotificationParser.Candidate candidate=fromEmail||recovered?new BankNotificationParser.Candidate(parsed,true,fromEmail?"Correo bancario: confirma el movimiento":"Aviso recuperado: comprueba que no esté registrado"):parsed;Detection.accept(this,source,candidate,sbn.getKey(),sbn.getPostTime());String status=NativeStore.settings(this).getString("lastDetection","");NativeStore.logNotice(this,selected,status.startsWith(selected.optString("label")+" · ")?status.substring((selected.optString("label")+" · ").length()):candidate.review?"Para revisar":"Movimiento reconocido",sbn.getPostTime());}catch(Exception error){try{NativeStore.logNotice(this,selected,"Error al procesar aviso",sbn.getPostTime());}catch(Exception ignored){}Detection.status(this,selected.optString("label"),"No se pudo registrar; revisa Diagnóstico");}});}
}

